"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[50983],{3331:(e,n,i)=>{i.d(n,{R:()=>a,x:()=>d});var r=i(36672);const t={},s=r.createContext(t);function a(e){const n=r.useContext(s);return r.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function d(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:a(e.components),r.createElement(s.Provider,{value:n},e.children)}},31438:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>o,contentTitle:()=>d,default:()=>h,frontMatter:()=>a,metadata:()=>r,toc:()=>l});const r=JSON.parse('{"id":"2023/03/30","title":"2023-03-30","description":"Homogenisierung des Designs: Vorteile und Nachteile","source":"@site/i18n/de/docusaurus-plugin-content-docs/current/2023/03/30.md","sourceDirName":"2023/03","slug":"/2023/03/30","permalink":"/de/2023/03/30","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/de/docusaurus-plugin-content-docs//current/2023/03/30.md","tags":[],"version":"current","frontMatter":{"localized_date":"30. M\xe4rz 2023","top_news":"Homogenisierung des Designs: Vorteile und Nachteile"},"sidebar":"defaultSidebar","previous":{"title":"2023-03-31","permalink":"/de/2023/03/31"},"next":{"title":"2023-03-29","permalink":"/de/2023/03/29"}}');var t=i(23420),s=i(3331);const a={localized_date:"30. M\xe4rz 2023",top_news:"Homogenisierung des Designs: Vorteile und Nachteile"},d="2023-03-30",o={},l=[{value:"Homogenisierung des Designs: Vorteile und Nachteile",id:"homogenisierung-des-designs-vorteile-und-nachteile",level:2},{value:"Binance k\xe4mpft &amp; Krypto-Debatte \xfcber Legitimit\xe4t",id:"binance-k\xe4mpft--krypto-debatte-\xfcber-legitimit\xe4t",level:2},{value:"Picsart AI ver\xf6ffentlicht Text2video-Zero Tool f\xfcr synthetische Videos",id:"picsart-ai-ver\xf6ffentlicht-text2video-zero-tool-f\xfcr-synthetische-videos",level:2},{value:"Ubuntu l\xe4sst Flatpak f\xfcr Snap fallen: Linux-Gemeinschaft reagiert",id:"ubuntu-l\xe4sst-flatpak-f\xfcr-snap-fallen-linux-gemeinschaft-reagiert",level:2},{value:"Cooler Master Case verwandelt Framework-Laptop in $39 Desktop",id:"cooler-master-case-verwandelt-framework-laptop-in-39-desktop",level:2},{value:"Disney schlie\xdft Metaverse inmitten von Kritik und Skepsis",id:"disney-schlie\xdft-metaverse-inmitten-von-kritik-und-skepsis",level:2},{value:"Sam Bankman-Frieds Verteidigung wird mit Spendengeldern finanziert",id:"sam-bankman-frieds-verteidigung-wird-mit-spendengeldern-finanziert",level:2},{value:"ChatGPT f\xfcr mehr Produktivit\xe4t in der Softwareentwicklung nutzen",id:"chatgpt-f\xfcr-mehr-produktivit\xe4t-in-der-softwareentwicklung-nutzen",level:2},{value:"Schrullen der Programmiersprache: Das &#39;Wat&#39;-Ph\xe4nomen",id:"schrullen-der-programmiersprache-das-wat-ph\xe4nomen",level:2},{value:"Google hat &quot;Beweismittelvernichtung&quot; begangen und gelogen, befand ein US-Richter",id:"google-hat-beweismittelvernichtung-begangen-und-gelogen-befand-ein-us-richter",level:2}];function u(e){const n={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"2023-03-30",children:"2023-03-30"})}),"\n",(0,t.jsx)(n.h2,{id:"homogenisierung-des-designs-vorteile-und-nachteile",children:"Homogenisierung des Designs: Vorteile und Nachteile"}),"\n",(0,t.jsxs)(n.p,{children:["Der Artikel er\xf6rtert den Trend zur Homogenisierung von Design und \xc4sthetik und beleuchtet dessen Vor- und Nachteile. Die Konvergenz des Designs ist sowohl auf Kunden- als auch auf Herstellerpr\xe4ferenzen zur\xfcckzuf\xfchren und zeigt sich in verschiedenen Branchen, darunter Automobilbau, Architektur und Branding. Die Diskussion wirft Fragen nach dem Gleichgewicht zwischen Optimierung und Kreativit\xe4t in Design und Wirtschaft auf und zeigt die m\xf6glichen Grenzen der Homogenisierung f\xfcr Innovation und Individualit\xe4t auf. Der Artikel stellt die Vorstellung in Frage, dass Menschen auf der ganzen Welt das Gleiche wollen, und argumentiert, dass sich die Verwirklichung von W\xfcnschen von Kultur zu Kultur unterscheidet. Der Moodboard-Effekt hat zu Blanding gef\xfchrt, aber es gibt eine Chance f\xfcr mutige, originelle Marken und Unternehmen, sich abzuheben.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35355703",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.alexmurrell.co.uk/articles/the-age-of-average",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"binance-k\xe4mpft--krypto-debatte-\xfcber-legitimit\xe4t",children:"Binance k\xe4mpft & Krypto-Debatte \xfcber Legitimit\xe4t"}),"\n",(0,t.jsxs)(n.p,{children:["Binance k\xe4mpft angesichts von Abfl\xfcssen in H\xf6he von 2 Milliarden Dollar, beh\xf6rdlichen Verboten und Kritik an fragw\xfcrdigen Praktiken. In der Zwischenzeit geht die Debatte \xfcber die Legitimit\xe4t von Kryptow\xe4hrungen und NFTs weiter, wobei einige B\xf6rsen und Projekte wegen roter Flaggen wie nicht registrierter Wertpapiere und mangelnder Einhaltung von Vorschriften kritisiert werden. Die Diskussion umfasst auch Argumente f\xfcr und gegen die Regulierung von Kryptow\xe4hrungen und die potenziellen Risiken, die mit Investitionen in sie verbunden sind. Die US-amerikanische CFTC verklagte k\xfcrzlich Binance wegen des Vorwurfs, illegal in den USA t\xe4tig zu sein und gegen die Handelsvorschriften zu versto\xdfen. Trotz der Bedenken bleibt der BNB-Token von Binance weitgehend unber\xfchrt, w\xe4hrend die Branche insgesamt einer st\xe4rkeren regulatorischen Aufsicht unterliegt.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35351805",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.wsj.com/articles/binance-sees-2-billion-in-outflows-as-troubles-compound-9a136e21",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"picsart-ai-ver\xf6ffentlicht-text2video-zero-tool-f\xfcr-synthetische-videos",children:"Picsart AI ver\xf6ffentlicht Text2video-Zero Tool f\xfcr synthetische Videos"}),"\n",(0,t.jsxs)(n.p,{children:["Picsart AI Research hat Text2Video-Zero ver\xf6ffentlicht, ein Tool, das synthetische Videos aus Eingabetexten mittels nat\xfcrlicher Sprachverarbeitung generiert. Der Code und die Gewichte f\xfcr das Modell sind verf\xfcgbar, so dass jeder seine eigene Instanz der Software auf einem System mit mindestens 12 GB VRAM ausf\xfchren kann. Die Ver\xf6ffentlichung hat trotz einiger sarkastischer Kommentare das Interesse der generativen KI-Community geweckt. Der KI sind jedoch Grenzen gesetzt, wenn es darum geht, Kunst zu schaffen, die menschliche Bed\xfcrfnisse und Emotionen anspricht, und KI-Modelle k\xf6nnen die kreative und k\xfcnstlerische Vision von menschlichen VFX-K\xfcnstlern nicht ersetzen. Das Tool Text-to-Video with Edge Guidance erzeugt Videos aus Texteingaben, einschlie\xdflich verschiedener Stile, und ist auf GitHub unter der CreativeML Open RAIL-M Lizenz verf\xfcgbar.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35352452",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://github.com/Picsart-AI-Research/Text2Video-Zero",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"ubuntu-l\xe4sst-flatpak-f\xfcr-snap-fallen-linux-gemeinschaft-reagiert",children:"Ubuntu l\xe4sst Flatpak f\xfcr Snap fallen: Linux-Gemeinschaft reagiert"}),"\n",(0,t.jsxs)(n.p,{children:["Canonical hat die Unterst\xfctzung f\xfcr Flatpak eingestellt und setzt nun ausschlie\xdflich auf Snap. Dies hat zu einer Kontroverse unter Linux-Anwendern gef\xfchrt, die die langsamen Update-Mechanismen und Einschr\xe4nkungen Snaps kritisieren. Benutzer sind auf alternative Distros wie Fedora und Linux Mint umgestiegen oder empfehlen anderen unfreie Debian-Images und PopOS, um Treiberprobleme zu l\xf6sen. Die Diskussion unterstreicht die Bedeutung von Benutzerkontrolle und -auswahl, die Frage, ob Anwendungsentwickler oder Distros Software paketieren sollten, und die Notwendigkeit standardisierter Paketformate. Einige Benutzer bevorzugen Flatpak gegen\xfcber Snap und \xe4u\xdfern sich besorgt \xfcber die Entscheidung von Canonical, w\xe4hrend andere den Wert beider Systeme f\xfcr \xe4ltere Versionen von Linux-Distributionen sehen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35354729",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://lwn.net/SubscriberLink/927262/6adb2350e2b0d2ce/",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"cooler-master-case-verwandelt-framework-laptop-in-39-desktop",children:"Cooler Master Case verwandelt Framework-Laptop in $39 Desktop"}),"\n",(0,t.jsxs)(n.p,{children:["Cooler Master bietet ein $39-Geh\xe4use an, das einen alten Framework-Laptop in einen Desktop-PC verwandelt, mit erweiterbarem Speicher und einem Standard-ATX-Netzteil. Die Benutzer von Hacker News begr\xfc\xdfen die Idee der Wiederverwendung alter Laptopteile, diskutieren aber auch \xfcber die Wiederverwendung und die Reduzierung von Elektroschrott. Framework zielt darauf ab, den Verbrauchern mit erweiterbaren CPU- und Speicheroptionen Geld zu sparen und den Elektroschrott zu reduzieren. Das Unternehmen bringt auch einen DIY-Desktop-PC auf den Markt, der 999 Dollar kostet und eine modulare, stromsparende und anpassbare Plattform darstellt. Framework Laptop, ein quelloffener, reparierbarer und aufr\xfcstbarer Laptop, wird als nachhaltige und erschwingliche Alternative zu herk\xf6mmlichen PC-Herstellern eingef\xfchrt. Framework kooperiert mit Cooler Master f\xfcr das transparente 39-Dollar-Geh\xe4use und stellt ein Proof-of-Concept-Akkugeh\xe4use und ein Akkupaket mit h\xf6herer Dichte f\xfcr seine Laptops vor.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35350288",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.theverge.com/2023/3/23/23652939/framework-cooler-master-sff-pc-case",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"disney-schlie\xdft-metaverse-inmitten-von-kritik-und-skepsis",children:"Disney schlie\xdft Metaverse inmitten von Kritik und Skepsis"}),"\n",(0,t.jsxs)(n.p,{children:["Disney hat seine Metaverse-Abteilung geschlossen, was zu Spekulationen f\xfchrte, das Projekt sei zu riskant. Kritiker der virtuellen Realit\xe4t (VR) f\xfchren Bedenken wegen Reisekrankheit, teurer Headsets und sozialer Isolation an. Einige argumentieren, dass die Einschr\xe4nkungen und Nachteile von VR sie zu einem unvern\xfcnftigen Konzept machen. Der Erfolg von Themenparks beruht auf emotionalen Bindungen, die durch VR-Erlebnisse nicht wiedergegeben werden k\xf6nnen. Die Schlie\xdfung der Metaverse-Abteilung hat Diskussionen \xfcber die Zukunft von VR und das Potenzial der Augmented-Reality-Technologie (AR) ausgel\xf6st. Die Idee des Metaverse wurde als reiner Hype-Zug kritisiert. Disneys Entscheidung, die Abteilung zu schlie\xdfen, deutet darauf hin, dass das Unternehmen seine Erwartungen an das Wachstum des Metaverse heruntergeschraubt hat. Kommentatoren sind neugierig auf die Zukunft von VR f\xfcr den Medien- und Unterhaltungsriesen.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35350952",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.wsj.com/articles/disney-eliminates-its-metaverse-division-as-part-of-companys-layoffs-plan-94b03650",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"sam-bankman-frieds-verteidigung-wird-mit-spendengeldern-finanziert",children:"Sam Bankman-Frieds Verteidigung wird mit Spendengeldern finanziert"}),"\n",(0,t.jsxs)(n.p,{children:["FTX-Gr\xfcnder Sam Bankman-Fried finanziert angeblich seine laufende Klageverteidigung mit Geld, das er seinem Vater geschenkt hat. Einige Kommentare auf Hacker News lassen vermuten, dass dies durch Buchhaltungstricks geschehen ist, um Steuern zu vermeiden. Anw\xe4lte haben eine berufliche Verantwortung, sicherzustellen, dass sie ethisch handeln und die Quelle der Gelder, mit denen sie bezahlt werden, \xfcberpr\xfcfen, da die Regierung rechtlich geltend machen kann, dass die Gelder aus Ertr\xe4gen aus Straftaten stammen. In einigen Kommentaren zu dem Artikel werden Bedenken hinsichtlich der Rechtm\xe4\xdfigkeit der von Bankman-Fried gesicherten 250-Millionen-Dollar-Anleihe sowie der M\xf6glichkeit der Beschlagnahme von Verm\xf6genswerten in F\xe4llen krimineller Aktivit\xe4ten ge\xe4u\xdfert. Andere er\xf6rtern die Berufsethik und kritisieren die hohen Geb\xfchren, die von Konkursverwaltern in R\xfcckforderungsf\xe4llen erhoben werden.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35358698",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.forbes.com/sites/sarahemerson/2023/03/29/sam-bankman-fried-legal-fees-funded-by-alameda-money-gifted-to-father-joe-bankman/",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"chatgpt-f\xfcr-mehr-produktivit\xe4t-in-der-softwareentwicklung-nutzen",children:"ChatGPT f\xfcr mehr Produktivit\xe4t in der Softwareentwicklung nutzen"}),"\n",(0,t.jsxs)(n.p,{children:["Der Einsatz von ChatGPT von OpenAI setzt sich in der Softwareentwicklung immer mehr durch und sorgt f\xfcr einen erheblichen Produktivit\xe4tsschub, insbesondere f\xfcr erfahrene Entwickler. Es wird jedoch in absehbarer Zeit keine Programmierer ersetzen, da Kreativit\xe4t, Probleml\xf6sungsf\xe4higkeiten und die F\xe4higkeit, gut im Team zu arbeiten, weiterhin unerl\xe4sslich sind. Investitionen in die Selbstautomatisierung und die Entwicklung von Tools k\xf6nnen jemanden zu einem \xe4u\xdferst produktiven und wertvollen Ingenieur machen. Der Artikel enth\xe4lt praktische Beispiele f\xfcr den Einsatz von KI-Technologie zur Steigerung der Produktivit\xe4t in der Softwareentwicklung. In den Kommentaren einiger erfahrener Programmierer werden Bedenken hinsichtlich der potenziellen Nachteile von KI-Tools ge\xe4u\xdfert, z. B. in Bezug auf die Wartbarkeit, das Debugging und die Auswirkungen auf Arbeitspl\xe4tze in der Softwareentwicklung. In den Kommentaren wird auch die Effektivit\xe4t des 10x-Programmierer-Konzepts sowie die Qualit\xe4t der Informatikausbildung und des Einstellungsverfahrens in der Tech-Industrie diskutiert.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35356054",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://kadekillary.work/posts/1000x-eng/",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"schrullen-der-programmiersprache-das-wat-ph\xe4nomen",children:"Schrullen der Programmiersprache: Das 'Wat'-Ph\xe4nomen"}),"\n",(0,t.jsxs)(n.p,{children:['Der Artikel hebt das "WAT"-Ph\xe4nomen in Programmiersprachen hervor, bei dem Macken im Verhalten verwirrend oder unerwartet sein k\xf6nnen. Er verweist auf einen Beitrag auf Hacker News und einen Reddit-Thread, in denen seltsame Verhaltensweisen in JavaScript bzw. Python diskutiert werden. Die Diskussion spiegelt die laufende Entwicklung von Programmiersprachen und die Bedeutung von Kontext, Konsistenz und Lesbarkeit wider. In dem Artikel wird auch ein Video von Gary Bernhardt mit dem Titel "WAT" besprochen, in dem einige der Merkw\xfcrdigkeiten in JavaScript gezeigt werden. Viele Kommentatoren bewundern das Video f\xfcr seinen kreativen Ansatz, obwohl es die Macken der Sprache aufzeigt.\n',(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35363044",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://www.destroyallsoftware.com/talks/wat",children:"Originaltext lesen"}),"."]}),"\n",(0,t.jsx)(n.h2,{id:"google-hat-beweismittelvernichtung-begangen-und-gelogen-befand-ein-us-richter",children:'Google hat "Beweismittelvernichtung" begangen und gelogen, befand ein US-Richter'}),"\n",(0,t.jsxs)(n.p,{children:["Ein US-Bundesrichter hat festgestellt, dass Google Beweise vernichtet und das Gericht belogen hat. Diese Feststellung hat schwerwiegende Folgen in einem Kartellverfahren. Der Richter entschied, dass Google-Mitarbeiter routinem\xe4\xdfig wesentliche Gesch\xe4ftsthemen besprachen, was zu dem negativen Schluss f\xfchren kann, dass die gel\xf6schten Beweise gegen Google gerichtet waren. Das Urteil bezieht sich auf Klagen von Epic Games und des Justizministeriums. Google hat es vers\xe4umt, die Chat-Aufzeichnungen wichtiger Mitarbeiter aufzubewahren. Der Richter hat Google noch nicht bestraft, aber es werden Geldstrafen verh\xe4ngt, sobald die Beweisaufnahme abgeschlossen ist. Unternehmen sind f\xfcr die Handlungen ihrer Mitarbeiter verantwortlich, und Personen, die f\xfcr die Vernichtung von Beweismitteln verantwortlich sind, sollten zur Rechenschaft gezogen werden. Kommentatoren schlagen eine Staffelung der Bu\xdfgelder auf der Grundlage des Umsatzes eines Unternehmens vor, \xe4hnlich wie bei den Bu\xdfgeldern der Banken zur Bek\xe4mpfung von Geldw\xe4sche und Terrorismusbek\xe4mpfung.\n",(0,t.jsx)(n.a,{href:"http://news.ycombinator.com/item?id=35363095",children:"Diskutieren Sie auf Discussion Service"})," oder ",(0,t.jsx)(n.a,{href:"https://storage.courtlistener.com/recap/gov.uscourts.cand.373179/gov.uscourts.cand.373179.469.0.pdf",children:"Originaltext lesen"}),"."]})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(u,{...e})}):u(e)}}}]);